import{_ as t,o as e,b as S,q as o}from"./chunks/framework.Tf23FRXt.js";const h=JSON.parse('{"title":"秘本宝库迦巴勒幻想图书馆","description":"","frontmatter":{},"headers":[{"level":2,"title":"进场 ~ BOSS 1","slug":"进场-boss-1","link":"#进场-boss-1","children":[]},{"level":2,"title":"BOSS 1 ~ BOSS 2","slug":"boss-1-boss-2","link":"#boss-1-boss-2","children":[{"level":3,"title":"BOSS 2 液态火焰","slug":"boss-2-液态火焰","link":"#boss-2-液态火焰","children":[]}]},{"level":2,"title":"BOSS 2 ~ BOSS 3","slug":"boss-2-boss-3","link":"#boss-2-boss-3","children":[{"level":3,"title":"BOSS 3 博学林鸮","slug":"boss-3-博学林鸮","link":"#boss-3-博学林鸮","children":[]}]}],"relativePath":"duty/196.htm.md","filePath":"duty/196.md","lastUpdated":1791098838000}'),l={name:"duty/196.htm.md"};function i(n,s,r,a,d,b){return e(),S("div",null,[...s[0]||(s[0]=[o('<h1 id="秘本宝库迦巴勒幻想图书馆" tabindex="-1">秘本宝库迦巴勒幻想图书馆</h1><p>曾经用来刷圣典的副本，所以很多玩家都会这里一波流。但是遇到新人也时常容易翻车。</p><h2 id="进场-boss-1" tabindex="-1">进场～BOSS 1</h2><p>只要减伤开好拉一波还是没太大困难的。</p><p>BOSS 1 <strong>书中恶魔</strong>出啥躲啥。</p><h2 id="boss-1-boss-2" tabindex="-1">BOSS 1 ~ BOSS 2</h2><p>很多 T 会在这里走错路… 也不是迷路反正就是习惯性的 hhh。也经常拉一波。</p><h3 id="boss-2-液态火焰" tabindex="-1">BOSS 2 液态火焰</h3><p><strong>液态火焰</strong>，A3 同模火基佬，技能都差不多。被连线冲锋的注意远离，BOSS 变为火龙卷时会点名正负极，和 BOSS 同极靠近 (因为相斥)，和 BOSS 异极远离 (因为会相吸)；BOSS 变为手掌时攻击上升，注意抬血。头顶出现太阳月亮徽章，找同色地板躲避。</p><h2 id="boss-2-boss-3" tabindex="-1">BOSS 2 ~ BOSS 3</h2><p>拉一波啦呱呱呱呱翻车啦呱呱呱呱。</p><h3 id="boss-3-博学林鸮" tabindex="-1">BOSS 3 博学林鸮</h3><p>金碟 75w 同模椅子可飞推荐。<strong>博学林鸮</strong>会扔好多书下来，需要根据 BOSS 读条技能去踩书里的效果。<mark>爆震之章</mark>→随便踩一本浮空；<mark>龙卷之章</mark>→踩黑色的圈；<mark>河童之章</mark>→变成河童之后踩绿色的圈。BOSS 扔完一圈书之后会召唤贝爷，如果 DPS 不够的话记得注意在陨石后面躲噶哦哦。</p>',13)])])}const B=t(l,[["render",i]]);export{h as __pageData,B as default};
